\label{app:cor:accuracy}
There are fixed $c,c',C_0,C_1>0$ such that the following hold.
For a prescribed cross-section of size $\mathcal A=M$ and
$L_\epsilon\ge C_0\mathcal A$, choose
\begin{align}
 m=\left\lfloor cL_\epsilon^{2/3}\mathcal A^{-1/3}\right\rfloor\ge3
 \label{app:eq:accuracy-choice}
\end{align}
in Theorem~\ref{app:thm:lower}. The resulting Hamiltonian satisfies
\begin{align}
 \log D_\epsilon(\Omega)\ge c'(\mathcal A L_\epsilon)^{2/3}.
 \label{app:eq:state-accuracy-theorem}
\end{align}
For the AGSP statement, first prescribe $0<\eta\le1/8$ with
$\log(1/\eta)\ge C_1\mathcal A$, and then choose the Hamiltonian using
\eqref{app:eq:accuracy-choice} with $\epsilon'=\sqrt2\eta$.
On this selected system, \emph{every} AGSP with
$\eta_K=\delta_K+\epsilon_K\le\eta$ satisfies
\begin{align}
 \log D_K\ge c'
 \left(\mathcal A\log\frac1\eta\right)^{2/3}.
 \label{app:eq:agsp-accuracy-theorem}
\end{align}
The one-dimensional family gives the same statements with $\mathcal A=1$.
For a common target accuracy $\epsilon$, setting $\eta=\epsilon$ and
choosing the construction for $\epsilon'=\sqrt2\epsilon$ gives both
state and AGSP lower bounds on the same Hamiltonian, after adjusting
the fixed constants; see Appendix~\ref{app:accuracy-proof}.

\label{app:lem:moment}
For $s_0=1/(4k)$,
\begin{align}
 \|e^{s_0D}\Omega\|\le e^{3b_\partial s_0},
 \qquad
 \|\mathbf1_{(T,\infty)}(D)\Omega\|
 \le e^{-s_0T+3b_\partial s_0}\quad(T\ge0).
 \label{app:eq:moment}
\end{align}

\label{app:lem:variational}
Let $G\ge0$ have a unique normalized zero-energy ground state $\Omega$ and
gap $\Delta>0$. For an orthogonal projection $P$ with $P\Omega\ne0$, set
\begin{align}
 G_P:=PGP\big|_{\operatorname{Ran}P},
 \qquad
 e_P:=\frac{\langle\Omega|PGP|\Omega\rangle}{\|P\Omega\|^2}.
 \label{app:eq:variational-energy}
\end{align}
If $e_P<\Delta$, the ground state $\Omega_P$ of $G_P$ is unique and,
when embedded in the original space with its phase aligned with $\Omega$,
\begin{align}
 0\le\lambda_0(G_P)\le e_P,
 \qquad \Delta_P\ge\Delta-e_P,
 \qquad \|\Omega_P-\Omega\|\le\sqrt{2e_P/\Delta}.
 \label{app:eq:variational-conclusions}
\end{align}
If $\operatorname{Ran}P$ is one-dimensional, the excited-state assertion
is vacuous.

\label{app:lem:cutcount}
Suppose $F$ is norm-absolutely convergent in a neighborhood of the closed
unit polydisc. For an integer $Q\ge0$, set
\begin{align}
 \delta_Q(F):=\sum_{|q|>Q}\|F_q\|,\qquad
 p_*:=\lfloor2Q/\ell\rfloor,\qquad
 N_{\mathrm{ph}}:=\ell(2Q+1)^{\lceil\log_2\ell\rceil}.
 \label{app:eq:cutcount-data}
\end{align}
There are indexed families $\mathcal Z_s$ of unit phases and coefficients
$C_{s,z}$ such that
\begin{align}
 F(\mathbf1)
 &=\sum_{s=1}^\ell\sum_{z\in\mathcal Z_s} C_{s,z}
       \sum_{p=0}^{p_*}[x^p]
       F(z_1,\ldots,z_{s-1},xz_s,z_{s+1},\ldots,z_\ell)+R_Q,
 \label{app:eq:cutcount}\\
 |z_t|&=1,\qquad |C_{s,z}|\le1,\qquad
 \sum_s|\mathcal Z_s|\le N_{\mathrm{ph}},\qquad
 \|R_Q\|\le2N_{\mathrm{ph}}\delta_Q(F).
 \label{app:eq:cutcount-error}
\end{align}

\label{app:lem:finite-rank}
Suppose $A_0=A_L\otimes I+I\otimes A_R$, $\|A_0\|\le W$, and
$\operatorname{SR}(B)\le R_B$. For $t\ge0$, $p\ge1$, and $0<\eta<1$,
\begin{align}
 D_{p,t}(A_0,B):=[x^p]e^{-t(A_0+xB)}
 \label{app:eq:Dpt}
\end{align}
has an approximation of operator-norm error at most $\eta$ and Schmidt
rank at most $[R_B(N_{\mathrm{ad}}+2)^2]^p$, where
\begin{align}
 N_{\mathrm{ad}}:=\left\lceil C_N\left[
 (p+1)tW+t\|B\|+\log(p+1)+\log(1/\eta)+1\right]\right\rceil.
 \label{app:eq:ad-degree}
\end{align}
Here $C_N$ is universal and sufficiently large. For $p=0$ the coefficient
has rank one exactly. Neither $A_0$ nor $B$ is required to be Hermitian.

Let $B_{A_0}(u)=e^{uA_0}Be^{-uA_0}$. The interaction representation gives
\begin{align}
 D_{p,t}=(-1)^p e^{-tA_0}
 \int_{0\le u_p\le\cdots\le u_1\le t}
 B_{A_0}(u_1)\cdots B_{A_0}(u_p)\,du_1\cdots du_p.
 \label{app:eq:interaction-picture}
\end{align}
Replace every conjugated insertion by
$B_{A_0,N}(u)=\sum_{q=0}^N u^q\operatorname{ad}_{A_0}^q(B)/q!$.
For a decomposition $B=\sum_{\beta=1}^{R_B}B_\beta^L\otimes B_\beta^R$,
\begin{align}
 \operatorname{ad}_{A_0}^q(B)=
 \sum_{\beta=1}^{R_B}\sum_{r=0}^q\binom qr
 \operatorname{ad}_{A_L}^r(B_\beta^L)
 \otimes\operatorname{ad}_{A_R}^{q-r}(B_\beta^R).
 \label{app:eq:common-basis}
\end{align}
All $u\in[0,t]$ therefore use the \emph{same} set of at most
$R_B(N+1)(N+2)/2\le R_B(N+2)^2$ product operators. Expand the product of
$p$ insertions in this fixed set and integrate only its scalar
coefficients. The prefactor $e^{-tA_0}=e^{-tA_L}\otimes e^{-tA_R}$ does
not increase the rank, which proves the stated rank bound. A bound on the
rank at each integration time alone would not suffice.

Since $\|\operatorname{ad}_{A_0}^q(B)\|\le(2W)^q\|B\|$,
\begin{align}
 \sup_{0\le u\le t}\|B_{A_0}(u)-B_{A_0,N}(u)\|
 &\le\|B\|\sum_{q>N}\frac{(2tW)^q}{q!}
 \le\|B\|e^{4tW}2^{-N},
 \label{app:eq:ad-tail}\\
 \max\{\|B_{A_0}(u)\|,\|B_{A_0,N}(u)\|\}
 &\le\|B\|e^{2tW}.
 \label{app:eq:ad-factors}
\end{align}
Telescoping the difference of the $p$-fold products and using the simplex
volume gives
\begin{align}
 \|D_{p,t}-\widetilde D_{p,t}\|
 \le p\frac{(t\|B\|)^p}{p!}\,e^{(2p+3)tW}2^{-N}.
 \label{app:eq:insertion-error}
\end{align}
The bounds $(t\|B\|)^p/p!\le e^{t\|B\|}$ and
$2p+3\le3(p+1)$ show that \eqref{app:eq:ad-degree} makes this at most
$\eta$. When $p=0$, use $e^{-tA_0}$ exactly.

\label{app:lem:poincare}
The best Poincar\'e constant of the row chain satisfies
\begin{align}
 \operatorname{Var}_\pi(f)\le8b^3\mathcal E(f,f),
 \qquad \tau:=\sup_{\operatorname{Var}_\pi(f)>0}
             \frac{\operatorname{Var}_\pi(f)}{\mathcal E(f,f)}
             \le8b^3.
 \label{app:eq:poincare-bound}
\end{align}
Equivalently, $\tau=1/\lambda_1(J_b)$, where $\lambda_1(J_b)$ is the
smallest positive eigenvalue.

\label{app:lem:history}
The isometry
\begin{align}
 W:|w\rangle\longmapsto|\chi_w\rangle,
 \qquad
 \mathcal H_{\mathrm{hist}}:=W\mathbb C^{\mathcal Q_b}
 \label{app:eq:history-isometry}
\end{align}
satisfies
\begin{align}
 J_{\mathrm{phys},b}W=WJ_b.
 \label{app:eq:intertwining}
\end{align}
For every normalized vector
$\psi_F\in\operatorname{span}\{\chi_w:w\in F_m\}$ there are fixed
isometries on the two sides such that
\begin{align}
 (\mathcal V_L\otimes\mathcal V_R)|\psi_F\rangle
       =|\Phi\rangle^{\otimes m}\otimes|\Xi\rangle,
 \qquad \|\Xi\|=1.
 \label{app:eq:row-Bell-factor}
\end{align}
The target projection can be chosen as $P_F=P_L\otimes I_R$ by counting
particles in the left half-row.

\label{app:lem:well}
Let $J_{\mathrm{phys}}\ge0$ preserve a legal subspace and its orthogonal
complement. Let $\Gamma$ vanish on the legal subspace and satisfy
$\Gamma\ge I$ on its complement. Let a projector $R_o$ preserve these
subspaces and restrict to $|o\rangle\langle o|$ on the legal subspace,
where $o$ is a normalized product state. If
$r_o:=\langle o|J_{\mathrm{phys}}|o\rangle\le1/2$, then
\begin{align}
 H_{\mathrm{raw}}=J_{\mathrm{phys}}+2\Gamma-R_o
 \label{app:eq:general-well}
\end{align}
has a unique negative eigenvalue $-\lambda_*$, with
$1-r_o\le\lambda_*\le1$. Its full-system gap is at least $\lambda_*$,
and its ground state obeys
\begin{align}
 |\langle o|\Omega\rangle|^2\ge\lambda_*\ge\tfrac12.
 \label{app:eq:well-overlap}
\end{align}
If an invariant history subspace contains $o$, the ground state belongs
to that history subspace.

\label{app:lem:startup}
Let $a^M$ denote the product row source in the fully active sector.
For every $t_0>0$,
\begin{align}
 \langle a^M|e^{-t_0\widehat J}|o\rangle
 \ge e^{-t_0}\left(\frac p2\right)^M\frac{t_0^M}{M!}.
 \label{app:eq:startup-amplitude}
\end{align}
In particular, at $t_0=M$ this is at least $e^{-C_{\mathrm{act}}M}$,
where $C_{\mathrm{act}}=1+\log(2/p)\le1+\log6$.

Set $G=\operatorname{diag}(\sqrt\pi)$ and
$\mathsf L=G^{-1}JG$. With
$q_{xy}=-J_{xy}\sqrt{\pi(y)/\pi(x)}\ge0$ for $x\ne y$, we have
\begin{align}
 (\mathsf Lf)(x)=\sum_{y\ne x}q_{xy}(f(x)-f(y)),\qquad
 c_{xy}=\pi(x)q_{xy}=c_{yx}.
 \label{app:eq:Doob-transform}
\end{align}
Thus $\mathsf L$ is the nonnegative-sign Markov Laplacian, whose
transition semigroup is $e^{-t\mathsf L}$, and
$\langle f,\mathsf Lg\rangle_\pi=\mathcal E(f,g)$.
In particular $J\ge0$. Define
\begin{align}
 h:=s(\mathsf L+sI)^{-1}\frac{\mathbf1_a}{p}.
 \label{app:eq:resolvent-density}
\end{align}
Connectivity and the positive resolvent kernel give $h>0$.
Stationarity gives $\mathbb E_\pi h=1$. At a positive maximum away from
$a$, $(\mathsf L+sI)h>0$ would contradict the resolvent equation, so
$h(a)=\max h\ge1$.

Take the $L^2(\pi)$ inner product of
$(\mathsf L+sI)h=s\mathbf1_a/p$ with $1/h$. Since
$\langle1/h,h\rangle_\pi=1$, this gives
\begin{align}
 -\mathcal E(1/h,h)=s\left(1-\frac1{h(a)}\right)\le s.
 \label{app:eq:log-energy-start}
\end{align}
For $x,y>0$, Cauchy--Schwarz applied to $\int_y^x dt/t$ shows
$(\log x-\log y)^2\le(x-y)^2/(xy)$. Hence
\begin{align}
 \mathcal E(\log h,\log h)
 \le-\mathcal E(1/h,h)\le s,
 \qquad \operatorname{Var}_\pi(\log h)\le s\tau.
 \label{app:eq:log-density-variance}
\end{align}
Let $\ell_h=\mathbb E_\pi\log h$. The source contribution to the variance
and $\log h(a)\ge0$ imply $\ell_h\ge-\sqrt{s\tau/p}$.
A second Cauchy--Schwarz bound gives
$|\mathbb E_{\pi(\cdot|F)}\log h-\ell_h|\le\sqrt{s\tau/q}$.
Therefore
\begin{align}
 \mathbb E_{\pi(\cdot|F)}\log h
 \ge-(p^{-1/2}+q^{-1/2})\sqrt{s\tau}.
 \label{app:eq:target-log-density}
\end{align}
Finally, the Doob transform gives the exact identity
\begin{align}
 s\langle v_F|(J+sI)^{-1}|a\rangle
       =\sqrt{pq}\,\mathbb E_{\pi(\cdot|F)}h.
 \label{app:eq:resolvent-density-identity}
\end{align}
Jensen's inequality completes the proof.

\label{app:cor:renyi}
For the states in Theorem~\ref{app:thm:lower} and every $0<\alpha<1$,
\begin{align}
 S_\alpha(\Omega_{M,m}^{(\nu)})
 \ge Mm\log2-C\frac{\alpha}{1-\alpha}
                   \left(M+\sqrt M\,m^{3/2}\right).
 \label{app:eq:renyi-theorem}
\end{align}
In two dimensions, for each fixed $\alpha$, taking
$m=\lfloor a_\alpha M\rfloor$ with a sufficiently small
$a_\alpha>0$ yields $S_\alpha\ge c_\alpha n$ for some
$c_\alpha>0$ independent of $n$, once the system is sufficiently large
at that fixed $\alpha$.
For every fixed $\nu\ge3$, take $R=32m+1$, $M=R^{\nu-1}$, and
$n=R^\nu$. This single hypercubic family, independent of $\alpha$,
satisfies
\begin{align}
 S_\alpha(\Omega_R^{(\nu)})
 \ge\frac{\log2}{32}R^\nu
       -O_\alpha\!\left(R^{\nu-1}+R^{(\nu+2)/2}\right),
 \qquad
 \liminf_{\substack{R\to\infty\\R=32m+1}}
 \frac{S_\alpha(\Omega_R^{(\nu)})}{R^\nu}
 \ge\frac{\log2}{32}.
 \label{app:eq:hypercube-theorem}
\end{align}
These conclusions hold for each fixed $\alpha<1$, not uniformly as
$\alpha\uparrow1$. Appendix~\ref{app:adiabatic} proves a von Neumann area law for the same states.

Regard a pure state as its coefficient matrix across $L|R$. Product
projection acts by contractions on its two sides. Every singular value
of the projected matrix is at most the corresponding singular value of
the original matrix. This follows, for example, by applying the
best-rank-$(j-1)$ operator-norm approximation characterization of the
$j$th singular value to $P_LXP_R^{\mathsf T}$ and any rank-$(j-1)$
approximation of $X$.
For $0<\alpha<1$, the Bell factor of dimension $d=2^{Mm}$ therefore
implies
\begin{align}
 \operatorname{tr}\rho_L^\alpha
 \ge w_{M,m}^{\alpha}d^{1-\alpha}
                    \operatorname{tr}\rho_{\Xi,L}^{\alpha}
 \ge w_{M,m}^{\alpha}d^{1-\alpha}.
 \label{app:eq:renyi-projection}
\end{align}
The last step uses normalization of $\Xi$: its eigenvalues lie in
$[0,1]$, and $x^\alpha\ge x$ there.
Taking logarithms and applying \eqref{app:eq:parallel-weight} gives
\begin{align}
 S_\alpha(\Omega_{M,m}^{(\nu)})
 \ge Mm\log2+\frac{\alpha}{1-\alpha}\log w_{M,m}
 \ge Mm\log2-C\frac{\alpha}{1-\alpha}
                  (M+\sqrt M\,m^{3/2}).
 \label{app:eq:renyi-finite-proof}
\end{align}

\paragraph{Two dimensions.}
Fix $0<\alpha<1$ and choose $a_\alpha>0$ such that
\begin{align}
 C\frac{\alpha}{1-\alpha}\sqrt{a_\alpha}\le\frac{\log2}{4}.
 \label{app:eq:aspect-choice}
\end{align}
For $m=\lfloor a_\alpha M\rfloor$ and sufficiently large $M$, the
transport term in \eqref{app:eq:renyi-finite-proof} is at most
$Mm\log2/4$, since $\sqrt M\,m^{3/2}=Mm\sqrt{m/M}$.
The startup term, proportional to $M$, is also at most $Mm\log2/4$
for all sufficiently large $M$. Thus
\begin{align}
 S_\alpha(\Omega_{M,m}^{(2)})\ge\tfrac12 Mm\log2
       \ge c_\alpha n,\qquad n=M(32m+1),
 \label{app:eq:2d-volume-proof}
\end{align}
with a positive coefficient $c_\alpha$ independent of $n$.
Only the rectangular aspect ratio depends on $\alpha$; the alphabet,
interaction range, strength normalization, and gap bound do not.

\paragraph{Dimensions three and above.}
Fix $\nu\ge3$, set $R=32m+1$, and take the cubic cross-section
$\Sigma=\{1,\ldots,R\}^{\nu-1}$. The embedding above gives a hypercube
with $M=R^{\nu-1}$ and $n=R^\nu$. Exactly,
\begin{align}
 Mm\log2=\frac{\log2}{32}(R^\nu-R^{\nu-1}),\qquad
 M=R^{\nu-1},\qquad
 \sqrt M\,m^{3/2}=O(R^{(\nu+2)/2}).
 \label{app:eq:hypercube-scaling}
\end{align}
For every fixed $0<\alpha<1$, substituting these expressions into
\eqref{app:eq:renyi-finite-proof} gives
\begin{align}
 S_\alpha(\Omega_R^{(\nu)})
 \ge\frac{\log2}{32}R^\nu
       -O_\alpha(R^{\nu-1}+R^{(\nu+2)/2}).
 \label{app:eq:hypercube-finish}
\end{align}
Both error exponents are strictly smaller than $\nu$ precisely when
$\nu>2$. Dividing by $R^\nu$ and taking the lower limit along
$R=32m+1$ proves \eqref{app:eq:hypercube-theorem}.
The Hamiltonian family has no $\alpha$-dependent geometric choice.
The correction nevertheless contains $\alpha/(1-\alpha)$, so its
convergence is not uniform as $\alpha\uparrow1$.
The same states obey a von Neumann area law by the independent gapped-path argument of Appendix~\ref{app:adiabatic}.

\label{app:prop:adiabatic-path}
For each lower-bound Hamiltonian constructed in
Appendices~\ref{app:row}--\ref{app:consequences}, write its unnormalized
physical operator as
\begin{align}
 H^{\rm raw}=J_{\rm phys}+2\Gamma-R_o.
 \label{app:eq:path-raw}
\end{align}
Here $J_{\rm phys}\ge0$ is the sum of propagation and, when present,
activation terms; $\Gamma$ is the sum of the local grammar penalties;
and $R_o$ is the local root-identifying projector. There is a fixed
normalization $g_*>0$ such that
\begin{align}
 H(s)=g_*^{-1}\bigl(sJ_{\rm phys}+2\Gamma-R_o\bigr),
 \qquad 0\le s\le1,
 \label{app:eq:adiabatic-path}
\end{align}
has a unique ground state $\Omega(s)$ for every $s$, with
\begin{align}
 \Omega(0)=o,\qquad \Omega(1)=\Omega,\qquad
 \Delta(s)\ge\frac{1-sr_o}{g_*}\ge\frac1{2g_*},
 \qquad r_o:=\langle o|J_{\rm phys}|o\rangle\le\tfrac12.
 \label{app:eq:path-gap}
\end{align}
The state $o$ is a product of on-site states. The paths have on-site
dimension at most six, interaction size at most five and range at most
two. Both their local interaction strength and the local strength of
$\partial_sH(s)$ are bounded uniformly. For the fixed planar cut,
\begin{align}
 S_1(\Omega(s))\le C_\nu\mathcal A,\qquad 0\le s\le1,
 \label{app:eq:path-area}
\end{align}
where $C_\nu$ is independent of $M,m,s$ and of the entropy index used to
select the endpoint family.

\label{app:lem:near-pure}
Let $\langle\Omega|\rho|\Omega\rangle=1-\delta>0$ and
$d_\delta:=\sqrt{2-2\sqrt{1-\delta}}\le\sqrt{2\delta}$.
For every integer $R\ge1$ and $0<\alpha<1$,
\begin{align}
 E_{p,\alpha}(\rho)\ge\log R+
 \kappa_\alpha\log\left(\sqrt{T_\Omega(R)}-d_\delta\right)_+^2.
 \label{app:eq:near-pure-transfer}
\end{align}
A zero argument of the logarithm gives no useful bound for that $R$.

The full excited-state weight satisfies
\begin{align}
 \delta_\beta:=1-\langle\Omega_m|\rho_{\beta,m}|\Omega_m\rangle
 =\frac{\sum_{j\ge1}e^{-\beta(E_j-E_0)}}
        {1+\sum_{j\ge1}e^{-\beta(E_j-E_0)}}
 \le(6^{32m}-1)e^{-\beta\Delta_0}.
 \label{app:eq:thermal-excited-weight}
\end{align}
This counts all physical excitations, including legal, non-history and
illegal sectors. Set $F=Cm^{3/2}$. The cooling condition in
\eqref{app:eq:thermal-1d-finite} implies $\delta_\beta\le e^{-F}/16$.
The one-dimensional Bell-sector construction gives
$T_{\Omega_m}(2^{m-1})\ge\tfrac12e^{-F}$. Consequently,
\begin{align}
 \left(\sqrt{T_{\Omega_m}(2^{m-1})}-d_{\delta_\beta}\right)_+^2
 \ge\left(\sqrt{e^{-F}/2}-\sqrt{e^{-F}/8}\right)^2
 =e^{-F}/8.
 \label{app:eq:thermal-tail-constant}
\end{align}
Lemma~\ref{app:lem:near-pure} with $R=2^{m-1}$ proves the claim.

\label{app:cor:thermal-1d}
There exist constants $c>0$, $\beta_0>0$ and $0<\alpha_0<1$ such that,
for every $\beta\ge\beta_0$ and $0<\alpha\le\alpha_0$,
\begin{align}
 \sup_{m\ge3}E_{p,\alpha}(\rho_{\beta,m})
 \ge c\min\!\left\{\beta^{2/3},\left(\frac{1-\alpha}{\alpha}\right)^2\right\}.
 \label{app:eq:thermal-1d-joint}
\end{align}
For a sufficiently small fixed $a>0$, taking
$\alpha=a\beta^{-1/3}$ and a suitable $m=\Theta(\beta^{2/3})$ gives
\begin{align}
 E_{p,\alpha}(\rho_{\beta,m})=\Theta(\beta^{2/3}).
 \label{app:eq:thermal-1d-diagonal}
\end{align}
The system size is selected for the prescribed $(\beta,\alpha)$.

\label{app:prop:gibbs-compression}
There are constants $B,c>0$ and $L_0$ such that, for every $L\ge L_0$,
with $\epsilon=e^{-L}$ and $\beta=BL$, one can choose a row with
$m=\Theta(L^{2/3})$ for which every operator $X$ obeying
\begin{align}
 \|X-\rho_{\beta,m}\|_1\le\epsilon
 \quad\text{has}\quad
 \log\operatorname{SR}(X)\ge cL^{2/3}
 \label{app:eq:gibbs-rank}
\end{align}
across the central cut. The operator need not be positive, normalized,
Hermitian, or exactly ground-state preserving.

Choose a fixed small $a>0$ with $Ca^{3/2}\le1$ and set
$m=\lfloor aL^{2/3}\rfloor\ge3$, so $F=Cm^{3/2}\le L$.
A fixed sufficiently large $B$ gives
$BL\Delta_0\ge L+32m\log6+\log2$ for every $L\ge L_0$.
By \eqref{app:eq:thermal-excited-weight} and commutation with
$P_0=|\Omega_m\rangle\langle\Omega_m|$,
\begin{align}
 \|\rho_{\beta,m}-P_0\|_1=2\delta_\beta\le e^{-L},
 \qquad \|X-P_0\|\le2e^{-L}.
 \label{app:eq:gibbs-ground-distance}
\end{align}
Choose the phase so $a_o=\langle\Omega_m|o\rangle\ge1/\sqrt2$.
Since $o$ is a product state, $v=Xo/a_o$ has
$\operatorname{SR}(v)\le\operatorname{SR}(X)$ and
$\|v-\Omega_m\|^2\le8e^{-2L}$.
If $\operatorname{SR}(X)\le2^{m-1}$, the established Schmidt-tail
bound gives instead
\begin{align}
 \|v-\Omega_m\|^2\ge\tfrac12e^{-Cm^{3/2}}
                      \ge\tfrac12e^{-L},
 \label{app:eq:gibbs-contradiction}
\end{align}
contradicting $L>\log16$. Thus $\operatorname{SR}(X)>2^{m-1}$.
